import{_ as t,o,c as d,a0 as a}from"./chunks/framework.BQvjZmTX.js";const u=JSON.parse('{"title":"Audit events","description":"","frontmatter":{},"headers":[],"relativePath":"reference/audit-events.md","filePath":"reference/audit-events.md"}'),s={name:"reference/audit-events.md"};function i(r,e,c,n,h,l){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="audit-events" tabindex="-1">Audit events <a class="header-anchor" href="#audit-events" aria-label="Permalink to &quot;Audit events&quot;">​</a></h1><p>The audit wire: one ndjson line on <strong>stderr</strong> per op outcome. arca keeps no local ledger (ADR-0001 — aggregation is peregrin&#39;s); the stderr stream <em>is</em> the contract, so a wrapper — peregrin, sepia, your own harness — can capture it, and a human sees a breadcrumb.</p><h2 id="shape" tabindex="-1">Shape <a class="header-anchor" href="#shape" aria-label="Permalink to &quot;Shape&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-01-01T00:00:00Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;actor&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;devin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;op&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;run&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;rref&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;billing/stripe&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dev&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;outcome&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>field</th><th>notes</th></tr></thead><tbody><tr><td><code>ts</code></td><td>RFC 3339, UTC</td></tr><tr><td><code>actor</code></td><td><code>--actor</code> → <code>ARCA_ACTOR</code> → <code>$USER</code>/<code>$LOGNAME</code> → <code>anon</code>. Self-claimed — attribution, not identity</td></tr><tr><td><code>op</code></td><td>the verb: <code>init put get list rm rotate run env check deploy ui serve manifest schema</code></td></tr><tr><td><code>rref</code></td><td>the resolved ref path, env pin stripped — same on <code>denied</code>/<code>error</code> when the arg parses, else the raw arg verbatim. <strong>Absent</strong> on op-scoped events</td></tr><tr><td><code>env</code></td><td>the env the op ran under</td></tr><tr><td><code>outcome</code></td><td><code>ok</code> | <code>denied</code> | <code>error</code></td></tr><tr><td><code>policy</code></td><td><strong>serve-path only, optional</strong> — the PDP verdict <code>{allow, reason?, obligations?}</code> behind the outcome; absent on every other path</td></tr></tbody></table><h2 id="when-events-fire" tabindex="-1">When events fire <a class="header-anchor" href="#when-events-fire" aria-label="Permalink to &quot;When events fire&quot;">​</a></h2><table tabindex="0"><thead><tr><th>event</th><th>meaning</th></tr></thead><tbody><tr><td><code>ok</code>, ref-scoped</td><td>one <strong>per ref</strong> materialized or mutated — <code>put</code>, <code>get</code>, <code>rotate</code>, <code>rm</code>, <code>deploy</code>, and per resolved ref inside <code>run</code>/<code>env</code></td></tr><tr><td><code>ok</code>, op-scoped</td><td>ref-less verb completed — <code>init</code>, <code>list</code>, <code>check</code>, <code>ui</code>, <code>serve</code></td></tr><tr><td><code>denied</code></td><td><code>[guardrails]</code> — or a serve-path PDP verdict of <code>allow: false</code> (including fail-closed on an unreachable PDP) — refused the op before it touched the vault; <code>rref</code> is the requested ref (normalized when parseable)</td></tr><tr><td><code>error</code></td><td>the op ran and failed — missing secret, vault i/o, bad ref; a <code>check</code> with findings also audits <code>error</code> (it exits 1); also emitted when config load itself fails (best-effort actor/env from flags + process env)</td></tr></tbody></table><p>Two deliberate silences:</p><ul><li><code>manifest</code>, <code>schema</code>, <code>gen-cli-docs</code> run before config load — pure introspection, no event.</li><li>A <code>run</code> child&#39;s non-zero exit is the <em>child&#39;s</em> outcome — no <code>error</code> event for it. arca&#39;s own exit code is the child&#39;s.</li></ul><h2 id="serve-and-the-policy-field" tabindex="-1"><code>serve</code> and the <code>policy</code> field <a class="header-anchor" href="#serve-and-the-policy-field" aria-label="Permalink to &quot;`serve` and the `policy` field&quot;">​</a></h2><p><code>arca serve</code> emits the same events — <code>get</code>/<code>put</code>/<code>rm</code>/<code>rotate</code> requests audit exactly like the CLI verbs, under the request&#39;s claimed <code>actor</code> when it carries one. The PDP consult covers the ops that can materialize — <code>get</code>/<code>put</code>/<code>rm</code>/<code>rotate</code> <em>and</em><code>list</code>/<code>check</code> (record decrypts, vault probes, scoped-token gets) — so a <code>check</code>&#39;s incidental token <code>get</code>s ride the same <code>policy</code>-bearing events. On the serve path only, every event a consulted <code>[serve.pdp]</code> gated gains a <code>policy</code> object — <code>{allow, reason?, obligations?}</code> — so the stream shows the verdict behind the outcome: a PDP allow, a PDP deny (<code>outcome: &quot;denied&quot;</code>, <code>policy.allow: false</code>), or a degraded allow recorded when <code>allow_on_error</code> overrode an unreachable PDP. The <code>serve</code> verb itself closes with one op-scoped <code>ok</code>. See <a href="./serve-protocol.html">the serve protocol</a>.</p><h2 id="ui-and-the-tui" tabindex="-1"><code>ui</code> and the TUI <a class="header-anchor" href="#ui-and-the-tui" aria-label="Permalink to &quot;`ui` and the TUI&quot;">​</a></h2><p><code>arca ui</code> emits one op-scoped <code>ok</code> when the browser exits cleanly. Inside it, browsing is silent — listing refs and metadata is not a materialization. The <code>r</code>→<code>r</code> reveal goes through the audited <code>get</code> path: a real <code>{&quot;op&quot;:&quot;get&quot;,&quot;rref&quot;:…,&quot;outcome&quot;:&quot;ok&quot;}</code> event per value shown.</p><h2 id="failure-posture" tabindex="-1">Failure posture <a class="header-anchor" href="#failure-posture" aria-label="Permalink to &quot;Failure posture&quot;">​</a></h2><p>Audit emission is best-effort: a closed stderr (broken pipe) never takes the broker down — the write error is swallowed by design.</p>',15)])])}const k=t(s,[["render",i]]);export{u as __pageData,k as default};
